#include "stdafx.h"#include "SignalTags.h"#ifdef _DEBUG#define new DEBUG_NEW#undef THIS_FILEstatic char THIS_FILE[] = __FILE__;#endifusing namespace std;KSignalTag::KSignalTag(): m_DecPics( 0 ), m_Number( 0 ), m_Block( 0 ), m_Out( 0 ){}void KSignalTag::SetDecPics( int dp ){  m_DecPics = dp;}int KSignalTag::GetDecPics(){  return m_DecPics;}void KSignalTag::SetDescription( LPCSTR pszDescr ){  m_szDescr = pszDescr;}LPCSTR KSignalTag::GetDescription() const{  return m_szDescr.c_str();}void KSignalTag::SetUnits( LPCSTR pszUnits ){  m_szEU = pszUnits;}LPCSTR KSignalTag::GetUnits() const{  return m_szEU.c_str();}void KSignalTag::SetAccess( LPCSTR pszA ){  m_szAccess = pszA;}void KSignalTag::SetDataType( LPCSTR pszDT ){  m_szDataType = pszDT;}void KSignalTag::SetNumber( int n ){  m_Number = n;}int KSignalTag::GetNumber(){  return m_Number;}void KSignalTag::SetInitialSourceValue( LPCSTR pszIS ){  m_szInitialSource = pszIS;  if( !m_szInitialSource.empty() && '\n'== *m_szInitialSource.rbegin() )    m_szInitialSource.resize( m_szInitialSource.length()-1 );}LPCSTR KSignalTag::GetInitialSourceValue(){  return m_szInitialSource.c_str();}void KSignalTag::SetBlockOut( short blk, short out ){  m_Block = blk;  m_Out = out;}//////////////////////////////////////////////////////////////////////////KAnalogSignalTag::KAnalogSignalTag(){}KAnalogSignalTag::KAnalogSignalTag( std::vector<std::string> &params ){  ASSD( params.at(6).at(0)=='R' );  for( size_t i=0; i<params.size(); i++ )  {    if( !params.at(i).compare("Analog") )    {      m_DecPics = atoi( params.at(i-1).c_str() );      string t = params.at(i-2);      if( t.at(0)!='R' )        m_szEU = t;    }  }}//////////////////////////////////////////////////////////////////////////KDigitalSignalTag::KDigitalSignalTag(){}KDigitalSignalTag::KDigitalSignalTag( std::vector<std::string> &params ){  ASSD( params.at(6).at(0)=='R' );  for( size_t i=0; i<params.size(); i++ )  {    if( !params.at(i).compare("Digital") )    {      m_DecPics = atoi( params.at(i-1).c_str() );      string t = params.at(i-2);      if( t.at(0)!='R' )        m_szEU = t;    }  }}